message.content:
{
  "gate_token": "HC5T-z4RtktDcRbYHAmk3A",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map at the edge of the ruined city.",
      "visual_description": "A windswept hill at dusk overlooks broken spires and tilted rooftops; an ink-stained coat flaps as a brass compass spins on a parchment map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp sparks awake with a warning.",
      "visual_description": "An oil lamp held aloft, its single fiery eye blinking open inside the flame, casting long orange shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts ahead through the rubble.",
      "visual_description": "A small clockwork fox with blue glass eyes darts between fallen statues, its key-wind tail ticking as moonlight glints off tin flanks.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver surfaces from a shattered window.",
      "visual_description": "A figure in a clear diving helmet rises out of a cracked stained-glass pane as if from water, coat shimmering with reflected city fires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They study the cursed tower from afar.",
      "visual_description": "A leaning black tower bleeds violet mist into the sky; four silhouettes crouch behind a toppled banner pole at the foreground.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle Lamp refuses to enter the gates.",
      "visual_description": "Massive iron castle gates yawn open; the lamp's flame flinches backward, its eye narrowed, while ink-stained fingers steady its handle.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox finds a hidden side passage.",
      "visual_description": "The clockwork fox paws at loose flagstones beside a ruined fountain, revealing a dark stairwell choked with old royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Sleeping Tax Collector blocks the corridor.",
      "visual_description": "A snoring official slumps across a stone hallway, ledger book under his cheek, stamped papers fluttering from his sleeves like dry leaves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara forges papers to slip past him.",
      "visual_description": "A compass-lit close-up of inked fingers pressing a stolen stamp onto parchment beside the snoring official's drooping hand.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Glass Diver slips through a tall mirror.",
      "visual_description": "A gilded mirror in a ruined ballroom ripples like water as the helmeted rescuer steps inside, coat dissolving into silver light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle Lamp warns of a patrol's torches.",
      "visual_description": "The lamp's eye widens at distant marching torchlight reflected in a puddle; ink-stained boots freeze mid-step beside it.",
      "characters": ["oracle_lamp", "mara_guarmara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox lures the armored patrol away.",
      "visual_description": "The clockwork fox scampers across a moonlit plaza, tail clicking loudly, while armored shapes chase its blue-eyed reflection into a dead-end alley.",
      "characters": ["tin_fox"]
    },
    {
      "guard_scene_number": 13,
      "scene_number": 13,
      "caption": "They reach the magic door of the inner keep.",
      "visual_description": "A circular door carved with shifting runes pulses with pale green light; the lamp's flame leans toward it as Mara traces a symbol with her compass.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver dives through the door's enchanted surface.",
      "visual_description": "The rescuer plunges headfirst into the rune-door as if into a pond, ripples of green light spreading outward across the stone.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, they find the Sleeping Tax Collector again, chained to a desk.",
      "visual_description": "A vaulted cell lit by a single shaft of moonlight; the official snores in iron cuffs, his ledger glowing faintly with confiscation seals.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox picks the lock on his chains.",
      "visual_description": "Close-up of tiny metal paws turning a hairpin inside an iron cuff; one blue glass eye reflects the lamp's worried flame.",
      "characters": ["tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group flees toward the river bridge as the city burns behind them.",
      "visual_description": "A long stone bridge stretches over black water; five figures sprint across it, silhouetted against orange flames consuming the cursed tower.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "On the far shore, Mara closes her map with a quiet smile.",
      "visual_description": "Dawn light on a misty riverbank; ink-stained hands fold a worn map while the lamp's eye dims to a gentle ember and the tin fox curls at her boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

